<?php

function gcd($a, $b) {
    if ($a > $b) {
        list($a, $b) = [$b, $a];
    }

    if ($a == 0 || $b == 0) {
        return $a + $b;
    }

    $result = 1;

    while (true) {
        $remain = $b % $a;

        if ($remain == 0) {
            $result *= $a;
            break;
        } else {
            $b = $a;
            $a = $remain;
        }
    }
    return $result;
}

// Read input
// Go: fmt.Scanf("%d %d %d", &simon, &antisimon, &stones)
// PHP: fscanf(STDIN, "%d %d %d", $simon, $antisimon, $stones);
$input = fopen("php://stdin", "r");
fscanf($input, "%d %d %d", $simon, $antisimon, $stones);

while (true) {
    // Simon plays
    $simonQuota = gcd($simon, $stones);

    if ($simonQuota <= $stones) {
        $stones -= $simonQuota;
    } else {
        echo "1\n";
        exit;
    }

    // Antisimon plays
    $antiQuota = gcd($antisimon, $stones);

    if ($antiQuota <= $stones) {
        $stones -= $antiQuota;
    } else {
        echo "0\n";
        exit;
    }
}
```

